#include <bits/stdc++.h>
using namespace std;using I=__int128_t;struct C{long long h,q,a,g,t,s,e;};vector<C> bank;
long long f(long long n){long long r=0;while(n){if(n&1)r+=(n>>1)+((n>>1)&1);n>>=1;}return r;}
struct Recipe{int c=-1,b=0;long long p=0,r=0;};
Recipe solve(long long N,int width){for(int j=0;j<80;j++){C c=bank[j];int b0=0;while(I(c.q)*c.q*(I(1)<<(2*b0))<=I(c.h)*N)b0++;for(int b=max(0,b0-width);b<=b0+width;b++){if(b>=27)continue;long long pow=1LL<<b;for(long long r=0;r<pow;r++){long long rev=0;for(int i=0;i<b;i++)rev=(rev<<1)|((r>>i)&1);long long L=2*pow-rev,K=c.q*L-c.g,D=c.a*L+c.h*(2*r+1-f(r))-c.t-c.e*(b?(r>>(b-1)):0);long long x=N-D;if(x<0)continue;if(x==0&&j!=0&&j!=16&&j!=48)return{j,b,0,r};long long lo=max(1LL,(x+K-1)/K),hi=(x-c.h+c.s)/(K-c.h);if(x-c.h+c.s<0)continue;for(long long p=lo;p<=hi;p++)if(K*p-c.h*f(p)-c.s*(p&1)+D==N)return{j,b,p,r};}}}return{};}
int main(int argc,char**argv){if(argc<4)return 2;ifstream in(argv[1]);C c;while(in>>c.h>>c.q>>c.a>>c.g>>c.t>>c.s>>c.e)bank.push_back(c);int width=atoi(argv[2]);if(string(argv[3])=="range"){long long cap=atoll(argv[4]);vector<long long>miss;for(long long N=23;N<=cap;N+=2)if(solve(N,width).c<0)miss.push_back(N);cout<<"{\"width\":"<<width<<",\"cap\":"<<cap<<",\"missing\":[";for(int i=0;i<(int)miss.size();i++){if(i)cout<<",";cout<<miss[i];}cout<<"]}\n";}else for(int i=3;i<argc;i++){long long N=atoll(argv[i]);auto z=solve(N,width);cout<<"{\"N\":"<<N<<",\"width\":"<<width<<",\"core\":"<<z.c<<",\"b\":"<<z.b<<",\"P\":"<<z.p<<",\"R\":"<<z.r<<"}\n";}}
